// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_27_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_28_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_29_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_35_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_36_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_37_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_43_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2'); } }, { id: "c_when_44_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_when_45_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }, { id: "c_when_78_txt", fn: function(){ return ((dma_comSprtSvcApplVO.get("dplmIsuTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.dplmIsuTpCd"); })()) === ''); } }, { id: "c_otherwise_79", fn: function(){ return (!(((dma_comSprtSvcApplVO.get("dplmIsuTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.dplmIsuTpCd"); })()) === ''))); } }, { id: "c_when_49", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "tr_57", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "tr_65", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'); } }, { id: "c_otherwise_82", fn: function(){ return (!(((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '3'))); } }, { id: "btn_fnPrint", fn: function(){ return ((dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '2' || (dma_comSprtSvcApplVO.get("comSchdlTpCd") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.comSchdlTpCd"); })()) === '4'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16609.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

