*/
scwin.btn_fnReport_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_fnReport_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnReport('' + dma_comSprtSvcApplVO.get("dplmIsuTpCd") + '',(String(((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })())) == null ? '' : ((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })())) == null ? '' : ((dma_comSprtSvcApplVO.get("chrgNm[(i-1)]") ?? (() => { throw new Error("unresolved:" + "comSprtSvcApplVO.chrgNm[(i-1)]"); })())))));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16609.btn_fnReport_onclick' }); }
};

