///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/support/comSprtSvc.do",
        ref: "dma_fnSearchReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil16609.tx_fnSearch" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fnReport
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fnReport = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_fnReportReq") ? $c.util.getComponent("dma_fnReportReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('ipt_method').setValue("comSprtSvcRsltInqList");
    $("form[name='comSprtSvcFrm']").attr("action", "comSprtSvc.do");
    $("form[name='comSprtSvcFrm']").attr("method", "post");
    $("form[name='comSprtSvcFrm']").attr("onsubmit", "");
    { const nr = await scwin.tx_fnSearch(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil16607/jldfil16607.xml", { "method": "comSprtSvcRsltInqList" }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnReport
 * @author Inswave
 * @date 2026. 09. 29
 * @param dplmIsuTpCd chrgNm
 * @returns
 * @hidden N
*/
scwin.fnReport = async function (dplmIsuTpCd, chrgNm) {
    /* sdd-asis-lifecycle:begin fnReport — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (dplmIsuTpCd === "1") {
        $c.util.getComponent('ipt_nTempleteCd').setValue("RLDFIL00046");
    } else {
        if (dplmIsuTpCd === "2") {
            $c.util.getComponent('ipt_nTempleteCd').setValue("RLDFIL00047");
        } else {
            await $c.win.alert("잘못된 교육구분코드 입니다.\n관리자에게 문의하세요.");
            return;
        }
    }
    $c.util.getComponent('ipt_eduCompltprnNm').setValue(chrgNm);
    await scwin.tx_fnReport();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnPrint
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnPrint = function () {
    /* sdd-asis-lifecycle:begin fnPrint — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const comSprtSvcPrint = '/jldfil16613/jldfil16613.xml';
    const optionCom = "scrollbars=yes,resizable=yes,toolbar=no,menubar=yes,width=820,height=350";
    (Promise.resolve($c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(comSprtSvcPrint), String((typeof optionCom !== 'undefined' ? optionCom : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "comSprtSvcPrint", scrollbars: true, resizable: true, width: "820", height: "350", type: "pageFramePopup" }, { id: '' }) : { id: "comSprtSvcPrint", scrollbars: true, resizable: true, width: "820", height: "350", type: "pageFramePopup" }), {})).then(function () {}), { closed: false, focus: function () {}, close: function () { $c.win.getScope().closePopup("comSprtSvcPrint"); this.closed = true; } });
    /* sdd-asis-lifecycle:end */
};
